cd /workspace/submission && find . -type f | sort && echo "--- sizes" && wc -c main.py crosscheck/*.py | tail -3 && echo "--- syntax+lint" && python3 -m py_compile main.py crosscheck/*.py && echo compiled && rm -rf __pycache__ crosscheck/__pycache__ && python3 -c "
import ast, sys, pathlib
for p in pathlib.Path('.').rglob('*.py'):
    tree = ast.parse(p.read_text())
    names = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)}
    imports = []
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom):
            imports += [a.asname or a.name for a in node.names]
        elif isinstance(node, ast.Import):
            imports += [(a.asname or a.name).split('.')[0] for a in node.names]
    unused = [i for i in imports if i and p.read_text().count(i) < 2]
    print(p, 'unused-imports:', unused)
